                       status=norm_status(f["status"].strip().upper())))
    return seq, out


def read_export(depot, text):
    if depot == "central":
        return read_xml(text)
    if depot == "north":
        return read_json(text)
    if depot == "south":
        return read_fixed(text)
    return read_delimited(depot, text)


# ---------------------------------------------------------------- main

def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        seq, records = read_export(depot, read_text(path))
        exports.setdefault(depot, []).append((seq if seq is not None else -1, name, records))

    corrections = resends = 0
    current = {}
    for depot, files in exports.items():
        files.sort(key=lambda x: (x[0], x[1]))
        cur = {}
        for _, _, records in files:
            for r in records:
                n = r["num"]
                if r["kind"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["kind"] == "correction":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(DEPOT_ORDER)}
    ranked = sorted(current, key=lambda d: (order.get(d, len(order)), d))
    owners = {}
    for d in ranked:
        for n in current[d]:
            owners.setdefault(n, []).append(d)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    depots = {d: [0, Decimal(0)] for d in current}
    months = {}
    for n, ds in owners.items():
        d = ds[0]
        r = current[d][n]
        if not counted(r["status"]) or r["date"] is None or r["kg"] is None:
            continue
        depots[d][0] += 1
        depots[d][1] += r["kg"]
        m = months.setdefault("%04d-%02d" % (r["date"].year, r["date"].month), [0, Decimal(0)])
        m[0] += 1
        m[1] += r["kg"]

    def fmt(v):
        return [v[0], float(v[1].quantize(Decimal("0.01"), ROUND_HALF_UP))]

    result = {
        "depots": {d: dict(zip(("shipments", "total_kg"), fmt(depots[d]))) for d in sorted(depots)},
        "months": {k: dict(zip(("shipments", "total_kg"), fmt(months[k]))) for k in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as fh:
        json.dump(result, fh, indent=2)
        fh.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
